INSERT INTO changelog (title, body, created_at) VALUES ('Картка клієнта на телефоні — зручна навігація', 'Смуга розділів (Огляд, Стратегія…) тепер закріплена під верхньою панеллю — лишається на місці, коли гортаєш. Справа в ній кнопка-сітка ▦: усі розділи клієнта плитками з іконками (і сховані, без даних — окремо). «Наступний крок» — одна плашка «Далі: …», тап — правка тексту і дати. У шапці на телефоні менше міток: максимум 2 тривоги і «+N».', datetime('now'));
